// Archive Member Path Preflight — DOM wiring.
// Safe DOM only: textContent / value. User input is never used as markup,
// style, selector, href, src, or a file name. No fetch, storage, analytics,
// or remote assets. The check runs in a module Worker built from
// the fixed embedded core bytes (js/worker-source.mjs, generated by the
// preview build); a Worker failure keeps the draft for retry.

import { createController } from './controller.mjs';
import { msg } from './i18n.mjs';

const lang = document.documentElement.lang === 'en' ? 'en' : 'zh-Hant';
const PAGE_SIZE = 25;
const EXAMPLE_ENTRIES = 'D\tdata\nF\tdata/a.txt\nF\tdata/b.txt';

function $(id) {
  return document.getElementById(id);
}

const entriesInput = $('entries-input');
const runButton = $('run-button');
const exampleButton = $('example-button');
const resetButton = $('reset-button');
const cancelButton = $('cancel-button');
const downloadButton = $('download-button');
const statusRegion = $('status');
const statusText = $('status-text');
const errorBox = $('error-box');
const errorText = $('error-text');
const exampleNote = $('example-note');
const resultSection = $('result-section');
const resultSummary = $('result-summary');
const unsafeBody = $('unsafe-table-body');
const unsafePager = $('unsafe-pager');
const unsafePrev = $('unsafe-prev');
const unsafeNext = $('unsafe-next');
const unsafePageInfo = $('unsafe-page-info');
const unsafeEmpty = $('unsafe-empty');
const conflictsBody = $('conflicts-table-body');
const conflictsPager = $('conflicts-pager');
const conflictsPrev = $('conflicts-prev');
const conflictsNext = $('conflicts-next');
const conflictsPageInfo = $('conflicts-page-info');
const conflictsEmpty = $('conflicts-empty');

let unsafePage = 0;
let conflictsPage = 0;
let exampleJustLoaded = false;
let previousStatus = 'empty';
let downloadUrl = null;
let downloadTimer = null;

function revokeDownload() {
  if (downloadUrl !== null) {
    URL.revokeObjectURL(downloadUrl);
    downloadUrl = null;
  }
  if (downloadTimer !== null) {
    clearTimeout(downloadTimer);
    downloadTimer = null;
  }
}

// Real worker factory: the Worker source is the fixed core bytes plus the
// fixed message handler, embedded at build time. User content never takes
// part in the program.
async function createRealWorker(callbacks) {
  const { WORKER_SOURCE } = await import('./worker-source.mjs');
  const url = URL.createObjectURL(
    new Blob([WORKER_SOURCE], { type: 'text/javascript' }),
  );
  const worker = new Worker(url, { type: 'module' });
  worker.onmessage = (event) => callbacks.onMessage(event.data);
  worker.onerror = () => callbacks.onError();
  return {
    postMessage(message) {
      worker.postMessage(message);
    },
    terminate() {
      worker.terminate();
      URL.revokeObjectURL(url);
    },
  };
}

function describeError(error) {
  if (error === null) return '';
  return msg(lang, `error${error.code}`, { row: error.row ?? '' });
}

function cell(text) {
  const td = document.createElement('td');
  td.textContent = text;
  return td;
}

function monoCell(text) {
  const td = cell(text);
  td.className = 'mono';
  return td;
}

function renderPage(rows, page, body, pager, prev, next, pageInfo, emptyNote) {
  while (body.firstChild !== null) body.removeChild(body.firstChild);
  const pages = Math.max(1, Math.ceil(rows.length / PAGE_SIZE));
  const current = Math.min(page, pages - 1);
  if (rows.length === 0) {
    pager.hidden = true;
    emptyNote.hidden = false;
    return { page: 0, pages };
  }
  emptyNote.hidden = true;
  const start = current * PAGE_SIZE;
  for (const row of rows.slice(start, start + PAGE_SIZE)) {
    body.appendChild(row);
  }
  if (pages > 1) {
    pager.hidden = false;
    prev.disabled = current === 0;
    next.disabled = current === pages - 1;
    pageInfo.textContent = msg(lang, 'pageInfo', {
      page: current + 1,
      pages,
      total: rows.length,
    });
  } else {
    pager.hidden = true;
  }
  return { page: current, pages };
}

function renderUnsafe(unsafe) {
  const rows = unsafe.map((item) => {
    const tr = document.createElement('tr');
    tr.appendChild(cell(String(item.line)));
    tr.appendChild(monoCell(item.code));
    tr.appendChild(cell(item.segment === null ? '—' : String(item.segment)));
    tr.appendChild(cell(describeError({ code: item.code, row: item.line })));
    return tr;
  });
  const state = renderPage(
    rows, unsafePage, unsafeBody, unsafePager, unsafePrev, unsafeNext,
    unsafePageInfo, unsafeEmpty,
  );
  unsafePage = state.page;
}

function renderConflicts(conflicts) {
  const rows = conflicts.map((item) => {
    const tr = document.createElement('tr');
    tr.appendChild(cell(msg(lang, `kind${item.kind}`)));
    tr.appendChild(monoCell(item.key));
    tr.appendChild(cell(item.lines.join(', ')));
    tr.appendChild(cell(msg(lang, `detail${item.kind}`)));
    return tr;
  });
  const state = renderPage(
    rows, conflictsPage, conflictsBody, conflictsPager, conflictsPrev,
    conflictsNext, conflictsPageInfo, conflictsEmpty,
  );
  conflictsPage = state.page;
}

function render(state) {
  const wasBusy = previousStatus === 'busy';
  previousStatus = state.status;

  statusRegion.setAttribute('aria-busy', state.status === 'busy' ? 'true' : 'false');
  runButton.disabled = state.status === 'busy';
  cancelButton.hidden = state.status !== 'busy';
  downloadButton.hidden = state.status !== 'success';
  exampleNote.hidden = !exampleJustLoaded;

  if (state.status === 'success' && state.result !== null) {
    unsafePage = 0;
    conflictsPage = 0;
    resultSection.hidden = false;
    const result = state.result;
    if (result.safeWithinPolicy) {
      resultSummary.textContent = msg(lang, 'summarySafe', { rows: result.rowCount });
    } else {
      resultSummary.textContent = msg(lang, 'summaryIssues', {
        rows: result.rowCount,
        unsafe: result.unsafe.length,
        conflicts: result.conflicts.length,
      });
    }
    renderUnsafe(result.unsafe);
    renderConflicts(result.conflicts);
  } else {
    resultSection.hidden = true;
  }

  if (state.status === 'error' && state.error !== null) {
    errorBox.hidden = false;
    errorText.textContent = describeError(state.error);
    entriesInput.setAttribute('aria-invalid', 'true');
    entriesInput.setAttribute('aria-errormessage', 'error-box');
    // Only a submission failure moves focus to the first error field.
    if (wasBusy) entriesInput.focus();
  } else {
    errorBox.hidden = true;
    errorText.textContent = '';
    entriesInput.removeAttribute('aria-invalid');
    entriesInput.removeAttribute('aria-errormessage');
  }

  if (state.status !== 'success') revokeDownload();

  if (state.status === 'empty') {
    statusText.textContent = msg(lang, 'statusEmpty');
  } else if (state.status === 'dirty') {
    statusText.textContent = exampleJustLoaded
      ? `${msg(lang, 'exampleLoaded')} ${msg(lang, 'statusDirty')}`
      : msg(lang, 'statusDirty');
  } else if (state.status === 'busy') {
    statusText.textContent = msg(lang, 'statusBusy');
  } else if (state.status === 'success') {
    statusText.textContent = `${msg(lang, 'statusSuccess')} ${msg(lang, 'reportReady')}`;
  } else if (state.status === 'error') {
    statusText.textContent = msg(lang, 'statusError');
  } else if (state.status === 'cancelled') {
    statusText.textContent = msg(lang, 'statusCancelled');
  }
}

const controller = createController({
  createWorker: createRealWorker,
  onChange: render,
});

entriesInput.addEventListener('input', () => {
  exampleJustLoaded = false;
  render(controller.setDraft(entriesInput.value));
});

runButton.addEventListener('click', () => {
  exampleJustLoaded = false;
  render(controller.run());
});

exampleButton.addEventListener('click', () => {
  exampleJustLoaded = true;
  entriesInput.value = EXAMPLE_ENTRIES;
  render(controller.loadExample(EXAMPLE_ENTRIES));
  entriesInput.focus();
});

resetButton.addEventListener('click', () => {
  exampleJustLoaded = false;
  entriesInput.value = '';
  render(controller.reset());
  entriesInput.focus();
});

cancelButton.addEventListener('click', () => {
  render(controller.cancel());
});

downloadButton.addEventListener('click', () => {
  const payload = controller.download();
  if (payload === null) return;
  revokeDownload();
  const blob = new Blob([payload.text], { type: 'application/json' });
  downloadUrl = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = downloadUrl;
  anchor.download = payload.filename;
  anchor.click();
  downloadTimer = setTimeout(revokeDownload, 30000);
});

unsafePrev.addEventListener('click', () => {
  const state = controller.getState();
  if (state.result === null) return;
  unsafePage = Math.max(0, unsafePage - 1);
  renderUnsafe(state.result.unsafe);
});

unsafeNext.addEventListener('click', () => {
  const state = controller.getState();
  if (state.result === null) return;
  unsafePage += 1;
  renderUnsafe(state.result.unsafe);
});

conflictsPrev.addEventListener('click', () => {
  const state = controller.getState();
  if (state.result === null) return;
  conflictsPage = Math.max(0, conflictsPage - 1);
  renderConflicts(state.result.conflicts);
});

conflictsNext.addEventListener('click', () => {
  const state = controller.getState();
  if (state.result === null) return;
  conflictsPage += 1;
  renderConflicts(state.result.conflicts);
});

window.addEventListener('pagehide', () => {
  controller.dispose();
  revokeDownload();
});

window.addEventListener('pageshow', (event) => {
  if (event.persisted) {
    exampleJustLoaded = false;
    entriesInput.value = '';
    render(controller.reset());
    entriesInput.focus();
  }
});

render(controller.getState());
